const concepts = data.concepts;

// Only consider concepts that PM already approved
const pmApproved = concepts.filter(c => {
  const status = c.pm_status || (c.fields && c.fields.pm_status);
  return status === 'Approved';
});

const approvedConcepts = concept_ids.length > 0
  ? pmApproved.filter(c => concept_ids.includes(c.id))
  : pmApproved;
const rejectedConcepts = concept_ids.length > 0
  ? pmApproved.filter(c => !concept_ids.includes(c.id))
  : [];

const items = [];

for (const c of approvedConcepts) {
  items.push({ json: {
    record_id: c.id,
    client_status: 'Approved',
    client_notes: notes || '',
    overall_status: 'Approved'
  }});
}

for (const c of rejectedConcepts) {
  items.push({ json: {
    record_id: c.id,
    client_status: 'Rejected',
    client_notes: notes || 'Not selected by client',
    overall_status: 'Client Review'
  }});
}

return items;

// ============================================================
// Count approved concepts and prepare to trigger Workflow 3
// ============================================================
const data = $('Merge Context').first().json;
