// ============================================================
const presentation = $input.first().json;
const data = $('Merge Context').first().json;
const concepts = data.concepts.filter(c => {
  const ids = data.concept_ids || [];
  return ids.length === 0 || ids.includes(c.id);
});
const brandName = data.project.brand_name || data.project.fields?.brand_name || 'Brand';
const today = new Date().toISOString().slice(0, 10);

if (!presentation.slides || presentation.slides.length < 2) {
  return [{ json: { deck_failed: true, error: 'Template needs at least 2 slides', presentationId: presentation.presentationId } }];
}

const presentationId = presentation.presentationId;
const templateSlideId = presentation.slides[1].objectId; // Slide 1 = concept template
const conceptCount = concepts.length;
const requests = [];

