  replaceAllText: {
    containsText: { text: '{{brand_name}}', matchCase: false },
    replaceText: brandName
  }
});
requests.push({
  replaceAllText: {
    containsText: { text: '{{date}}', matchCase: false },
    replaceText: today
  }
});

