    framework: c.framework || '',
    platform: c.platform || '',
    emotional_journey: c.emotional_journey || '',
    funnel_stage: c.funnel_stage || '',
    reference_url: c.reference_video_url || ''
  })),
  deck_failed: false
} }];

// ============================================================
// Build per-slide replaceAllText + reference video thumbnails
// Google Slides API auto-calculates scaleX/Y from size; transform sets position
// ============================================================
const dupData = $('Build Duplicate Requests').first().json;

if (dupData.deck_failed) {
  return [{ json: { deck_failed: true, presentationId: dupData.presentationId, deck_link: '' } }];
}

const presentation = $input.first().json;
const concepts = dupData.concepts;
const conceptCount = dupData.conceptCount;
const presentationId = dupData.presentationId;

if (!presentation.slides) {
  return [{ json: { deck_failed: true, presentationId, deck_link: '' } }];
}

const conceptSlides = presentation.slides.slice(1, 1 + conceptCount);
const extraSlides = presentation.slides.slice(1 + conceptCount, -1);

const requests = [];

// Delete extra duplicate slides
for (const slide of extraSlides) {
  requests.push({ deleteObject: { objectId: slide.objectId } });
}

// For each concept, replace text scoped to that slide
for (let i = 0; i < conceptCount && i < conceptSlides.length; i++) {
  const concept = concepts[i];
  const slideId = conceptSlides[i].objectId;

  const replacements = {
    '{{concept_number}}': String(i + 1),
    '{{concept_name}}': concept.concept_name,
    '{{hook_text}}': concept.hook_text,
    '{{concept_pitch}}': concept.concept_pitch,
    '{{format}}': concept.format,
    '{{platform}}': concept.platform,
    '{{framework}}': concept.framework,
    '{{emotional_journey}}': concept.emotional_journey,
    '{{funnel_stage}}': concept.funnel_stage,
    '{{reference_url}}': concept.reference_url
  };

  for (const [placeholder, value] of Object.entries(replacements)) {
    requests.push({
      replaceAllText: {
        containsText: { text: placeholder, matchCase: false },
        replaceText: value || '',
        pageObjectIds: [slideId]
      }
    });
  }

  // Add reference video thumbnail if URL is YouTube
  if (concept.reference_url) {
    let thumbnailUrl = '';
    const ytMatch = concept.reference_url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/shorts\/)([a-zA-Z0-9_-]{11})/);
    if (ytMatch) {
      thumbnailUrl = 'https://img.youtube.com/vi/' + ytMatch[1] + '/hqdefault.jpg';
    }

    if (thumbnailUrl) {
      const thumbId = 'thumb_' + i;
      const EMU = 914400;
      // Single createImage with size + transform
      // API auto-calculates scaleX/Y from size; translateX/Y positions the image
      // Size: 2.8" x 2.1" (4:3 aspect ratio matching YouTube thumbnails)
      // Position: right side of slide at (6.2", 1.5")
      requests.push({
        createImage: {
          objectId: thumbId,
          url: thumbnailUrl,
          elementProperties: {
            pageObjectId: slideId,
            size: {
              width: { magnitude: Math.round(2.8 * EMU), unit: 'EMU' },
              height: { magnitude: Math.round(2.1 * EMU), unit: 'EMU' }
            },
            transform: {
              scaleX: 1,
              scaleY: 1,
              shearX: 0,
              shearY: 0,
              translateX: Math.round(6.2 * EMU),
              translateY: Math.round(1.5 * EMU),
              unit: 'EMU'
            }
          }
        }
      });
    }
  }
}

const deckLink = 'https://docs.google.com/presentation/d/' + presentationId + '/edit';

return [{ json: {
  presentationId,
  requests: JSON.stringify({ requests }),
  deck_link: deckLink,
  deck_failed: false
} }];
